var TOEIC_PART2 = [
  ["When is the sales meeting?", "At three o'clock this afternoon.", "In the conference room.", "Yes, I'll be there.", 'C\xE2u h\u1ECFi "When" \u2192 tr\u1EA3 l\u1EDDi b\u1EB1ng th\u1EDDi gian.'],
  ["Where can I find the printer paper?", "In the supply closet.", "About twenty dollars.", "Yes, it works well.", 'C\xE2u h\u1ECFi "Where" \u2192 tr\u1EA3 l\u1EDDi b\u1EB1ng \u0111\u1ECBa \u0111i\u1EC3m.'],
  ["Who is in charge of the new project?", "Ms. Lopez from marketing.", "Next Monday.", "Around the corner.", '"Who" \u2192 tr\u1EA3 l\u1EDDi b\u1EB1ng ng\u01B0\u1EDDi.'],
  ["How long will the training take?", "About two hours.", "By train.", "In the morning.", '"How long" \u2192 kho\u1EA3ng th\u1EDDi gian.'],
  ["Why was the flight canceled?", "Because of the storm.", "At gate twelve.", "I like flying.", '"Why" \u2192 tr\u1EA3 l\u1EDDi b\u1EB1ng l\xFD do (Because...).'],
  ["Would you like some coffee?", "No, thanks. I just had some.", "Yes, it's on the table at noon.", "I went to the coffee shop.", "L\u1EDDi m\u1EDDi \u2192 ch\u1EA5p nh\u1EADn ho\u1EB7c t\u1EEB ch\u1ED1i l\u1ECBch s\u1EF1."],
  ["Could you send me the report by Friday?", "Sure, I'll email it tomorrow.", "It was very long.", "On the second floor.", "L\u1EDDi y\xEAu c\u1EA7u \u2192 \u0111\u1ED3ng \xFD v\xE0 n\xF3i c\xE1ch th\u1EF1c hi\u1EC7n."],
  ["Haven't you finished the presentation yet?", "Almost. I just need to add the charts.", "Yes, at the conference.", "It's a long presentation room.", "C\xE2u h\u1ECFi ph\u1EE7 \u0111\u1ECBnh \u2192 tr\u1EA3 l\u1EDDi t\xECnh tr\u1EA1ng ho\xE0n th\xE0nh."],
  ["Should we take a taxi or the subway?", "The subway is faster at this hour.", "Yes, I took a taxi.", "It costs ten dollars.", 'C\xE2u h\u1ECFi l\u1EF1a ch\u1ECDn "A or B" \u2192 ch\u1ECDn m\u1ED9t.'],
  ["Do you know when the new employee starts?", "I think it's next Monday.", "She's from Canada.", "For three years.", "C\xE2u h\u1ECFi gi\xE1n ti\u1EBFp v\u1EC1 th\u1EDDi gian."],
  ["How much does this laptop cost?", "It's on sale for eight hundred dollars.", "Very much, thank you.", "It's in the box.", '"How much" (gi\xE1 ti\u1EC1n) \u2192 tr\u1EA3 l\u1EDDi b\u1EB1ng s\u1ED1 ti\u1EC1n.'],
  ["Why don't we order lunch for the team?", "That's a great idea.", "Because I'm late.", "The lunch was delicious.", `"Why don't we...?" l\xE0 l\u1EDDi \u0111\u1EC1 ngh\u1ECB \u2192 \u0111\u1ED3ng \xFD.`],
  ["What time does the bank close?", "At five thirty on weekdays.", "Next to the post office.", "Yes, I have an account.", '"What time" \u2192 gi\u1EDD c\u1EE5 th\u1EC3.'],
  ["Who should I give this invoice to?", "Give it to the accounting office.", "It's due in June.", "Yes, it's invoiced.", '"Who ... to" \u2192 ng\u01B0\u1EDDi/b\u1ED9 ph\u1EADn nh\u1EADn.'],
  ["Is the client coming in person or joining online?", "She'll join us online.", "Yes, the client called.", "At the front desk.", 'C\xE2u h\u1ECFi l\u1EF1a ch\u1ECDn \u2192 ch\u1ECDn "online".'],
  ["I can't find my access card.", "Did you check the front desk?", "It's a red card.", "I access the files daily.", "T\xECnh hu\u1ED1ng than phi\u1EC1n \u2192 g\u1EE3i \xFD gi\u1EA3i ph\xE1p."],
  ["What did you think of the new policy?", "It seems fair to me.", "It was on the board.", "Yes, I did think.", '"What did you think of...?" h\u1ECFi \xFD ki\u1EBFn.'],
  ["Where should we hold the year-end party?", "The Grand Hotel has a nice hall.", "It starts at seven.", "Last December.", '"Where" \u2192 \u0111\u1ECBa \u0111i\u1EC3m \u0111\u1EC1 xu\u1EA5t.'],
  ["Has the delivery arrived?", "Not yet, but it's on its way.", "It's a deliver route.", "Yes, I arrived early.", "C\xE2u h\u1ECFi Yes/No v\u1EC1 hi\u1EC7n t\u1EA1i ho\xE0n th\xE0nh."],
  ["You're attending the workshop tomorrow, aren't you?", "Yes, I signed up last week.", "It was a long walk.", "The workshop room is blue.", "C\xE2u h\u1ECFi \u0111u\xF4i \u2192 tr\u1EA3 l\u1EDDi x\xE1c nh\u1EADn."],
  ["How often do you back up your files?", "Every evening before I leave.", "By the window.", "Yes, quite often.", '"How often" \u2192 t\u1EA7n su\u1EA5t.'],
  ["Which desk is mine?", "The one by the window.", "Two years ago.", "It's made of wood.", '"Which" \u2192 ch\u1ECDn m\u1ED9t \u0111\u1ED1i t\u01B0\u1EE3ng c\u1EE5 th\u1EC3.'],
  ["Do you mind if I open the window?", "Not at all, go ahead.", "It's a large window.", "Yes, it opened at noon.", '"Do you mind if...?" \u2192 "Not at all" = kh\xF4ng phi\u1EC1n.'],
  ["What's the deadline for the application?", "It closes at the end of the month.", "I applied last week.", "On the application form.", '"deadline" \u2192 th\u1EDDi h\u1EA1n.'],
  ["Why is the copy machine making that noise?", "It needs to be repaired.", "Three copies, please.", "He makes a lot of noise.", "H\u1ECFi l\xFD do \u2192 gi\u1EA3i th\xEDch nguy\xEAn nh\xE2n."]
];
