// src/app/data/exam/tests/helpers.ts
var TFNG2 = { T: "True", F: "False", NG: "Not Given" };
function mcq(x) {
  if (x[0] === "T" || x[0] === "F" || x[0] === "NG") {
    const a = TFNG2[x[0]];
    return { q: x[1], a, wrong: Object.values(TFNG2).filter((v) => v !== a), ex: x[2] };
  }
  return { q: x[0], a: x[1], wrong: x.slice(2, -1), ex: x[x.length - 1] };
}
var fills = (f) => f?.map(([q, answers, ex]) => ({ q, answers, ex }));
function audio(id, r) {
  return {
    id,
    title: r.title,
    titleVi: r.title,
    lines: r.lines.map((l) => ({ who: l.startsWith("M: ") ? "B" : "A", text: l.replace(/^[WM]: /, ""), vi: "" })),
    mcq: r.qs.map(mcq),
    fill: fills(r.fill),
    graphic: r.graphic ? { title: r.graphic[0], text: r.graphic[1] } : void 0
  };
}
function passage(id, r) {
  return { id, title: r.title, titleVi: r.title, text: r.text, textVi: "", mcq: r.qs.map(mcq), fill: fills(r.fill) };
}
function toeicTest(no, d) {
  const id = `tt${no}`;
  return {
    no,
    part2: d.p2,
    part5: d.p5,
    part3: d.p3.map((r, i) => audio(`${id}-p3-${i + 1}`, r)),
    part4: d.p4.map((r, i) => audio(`${id}-p4-${i + 1}`, r)),
    part6: d.p6.map((r, i) => passage(`${id}-p6-${i + 1}`, r)),
    part7: d.p7.map((r, i) => passage(`${id}-p7-${i + 1}`, r))
  };
}
var TIPS_TASK1 = [
  "\u0110o\u1EA1n 1: di\u1EC5n \u0111\u1EA1t l\u1EA1i \u0111\u1EC1 b\u1EB1ng l\u1EDDi c\u1EE7a b\u1EA1n (paraphrase).",
  "Vi\u1EBFt Overview n\xEAu 2 \u0111\u1EB7c \u0111i\u1EC3m n\u1ED5i b\u1EADt nh\u1EA5t, ch\u01B0a c\u1EA7n s\u1ED1 li\u1EC7u.",
  "Th\xE2n b\xE0i: nh\xF3m s\u1ED1 li\u1EC7u gi\u1ED1ng nhau \u0111\u1EC3 so s\xE1nh, kh\xF4ng li\u1EC7t k\xEA t\u1EEBng con s\u1ED1.",
  "Kh\xF4ng n\xEAu \xFD ki\u1EBFn c\xE1 nh\xE2n trong Task 1."
];
